def compute_affine_from_corners(world_tl, world_br, pixel_tl, pixel_br):
    x_tl, y_tl = world_tl
    x_br, y_br = world_br
    u_tl, v_tl = pixel_tl
    u_br, v_br = pixel_br

    # straightforward scales
    sx = (u_br - u_tl) / (x_br - x_tl)
    sy = (v_br - v_tl) / (y_br - y_tl)  # note: y_br - y_tl, not flipped

    ox = u_tl - sx * x_tl
    oy = v_tl - sy * y_tl

    return sx, ox, sy, oy

def world_to_pixel(x, y, sx, ox, sy, oy):
    u = sx * x + ox
    v = sy * y + oy
    return u, v


